import React, { useState, useEffect, useCallback } from 'react';
import { Container, Row, Col, Card, Table, Badge, Button, Form, InputGroup, Modal } from 'react-bootstrap';
import { toast } from 'react-toastify';
import { bpmnAPI, logistikAPI, adminAPI } from '../../services/api';

const RoomBookings = () => {
  const [bookings, setBookings] = useState([]);
  const [filteredBookings, setFilteredBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    status: 'all',
    requestType: 'all',
    search: '',
    dateFrom: '',
    dateTo: ''
  });

  // Modal states - hanya untuk kompatibilitas jika ada yang mengakses
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [selectedBooking, setSelectedBooking] = useState(null);

  useEffect(() => {
    fetchBookings();
  }, []);

  // Langsung set filteredBookings sama dengan bookings tanpa filtering
  useEffect(() => {
    console.log('📊 [NO FILTER] Setting filteredBookings directly from bookings:', bookings.length);
    setFilteredBookings(bookings);
  }, [bookings]);

  const fetchBookings = async () => {
    try {
      setLoading(true);
      console.log('🔄 [ROOM BOOKINGS] Fetching room bookings history for logistik...');
      
      // Use same logic as LogistikDashboard - prioritize adminAPI
      let requests = [];

      try {
        // Prioritas utama: gunakan Admin API untuk mendapatkan SEMUA requests
        console.log('🔍 [ROOM BOOKINGS] Fetching all requests for history...');
        const requestsResponse = await adminAPI.getAllRequests();
        console.log('✅ [ROOM BOOKINGS] Admin API success:', requestsResponse);
        
        let allRequests = [];
        if (requestsResponse.data && requestsResponse.data.success && requestsResponse.data.data) {
          allRequests = requestsResponse.data.data;
          console.log('✅ [ROOM BOOKINGS] Got requests from success wrapper:', allRequests.length);
        } else if (Array.isArray(requestsResponse.data)) {
          allRequests = requestsResponse.data;
          console.log('✅ [ROOM BOOKINGS] Got requests from direct array:', allRequests.length);
        } else {
          console.log('⚠️ [ROOM BOOKINGS] Unexpected response structure:', requestsResponse.data);
          allRequests = [];
        }
        
        console.log('🔍 [ROOM BOOKINGS] Sample request data:', allRequests.length > 0 ? allRequests[0] : 'No requests');
        
        // Filter for room-related requests only (room dan both)
        requests = allRequests.filter(req => {
          const isRoomOrBoth = req.request_type === 'room' || req.request_type === 'both';
          console.log('🔍 [ROOM BOOKINGS] Request', req.id, '- Type:', req.request_type, '- Include:', isRoomOrBoth);
          return isRoomOrBoth;
        });
        console.log('✅ [ROOM BOOKINGS] Got', requests.length, 'room-related requests from', allRequests.length, 'total requests');
        
      } catch (adminError) {
        console.log('⚠️ [ROOM BOOKINGS] Admin API failed:', adminError);
        requests = [];
      }

      // Sort by date (newest first) 
      const sortedRequests = requests.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
      setBookings(sortedRequests);
      
      console.log('✅ [ROOM BOOKINGS] Bookings loaded successfully:', sortedRequests.length, 'items');
      
    } catch (error) {
      console.error('❌ [ROOM BOOKINGS] Error fetching bookings:', error);
      setBookings([]);
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (key, value) => {
    // Temporarily disabled filtering
    console.log('� Filter change ignored (filtering disabled):', key, value);
  };
  const getStatusBadge = (booking) => {
    const status = booking.room_status || booking.status;
    const variants = {
      pending: 'warning',
      approved: 'success',
      rejected: 'danger',
      completed: 'info'
    };
    
    const labels = {
      pending: 'PENDING',
      approved: 'APPROVED',
      rejected: 'REJECTED',
      completed: 'COMPLETED'
    };
    
    return (
      <Badge bg={variants[status] || 'secondary'}>
        {labels[status] || status?.toUpperCase() || 'UNKNOWN'}
      </Badge>
    );
  };

  const getRequestTypeBadge = (type) => {
    const variants = {
      room: 'success',
      both: 'warning'
    };
    
    const labels = {
      room: 'Ruangan Only',
      both: 'Ruangan + Zoom'
    };
    
    return <Badge bg={variants[type] || 'secondary'}>{labels[type] || type}</Badge>;
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('id-ID', {
      weekday: 'short',
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  const handleDetail = (booking) => {
    setSelectedBooking(booking);
    setShowDetailModal(true);
  };

  const formatDateTime = (dateString) => {
    if (!dateString) return '-';
    return new Date(dateString).toLocaleString('id-ID', {
      day: 'numeric',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  if (loading) {
    return (
      <Container fluid className="py-4">
        <div className="text-center">
          <div className="spinner-border" role="status">
            <span className="visually-hidden">Loading...</span>
          </div>
        </div>
      </Container>
    );
  }

  return (
    <Container fluid className="py-4">
      {/* Header */}
      <Row className="mb-4">
        <Col>
          <h2 className="mb-0">
            <i className="fas fa-history me-2 text-success"></i>
            History Booking Ruangan
          </h2>
          <p className="text-muted">
            Riwayat semua pengajuan ruangan yang masuk ke logistik (room & zoom+room)
          </p>
        </Col>
      </Row>

      {/* Statistics */}
      <Row className="mb-4">
        <Col md={3}>
          <Card className="text-center border-0 shadow-sm">
            <Card.Body>
              <div className="display-6 text-primary mb-2">
                <i className="fas fa-list"></i>
              </div>
              <h4 className="mb-1">{filteredBookings.length}</h4>
              <p className="text-muted mb-0">Total Filtered</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center border-0 shadow-sm">
            <Card.Body>
              <div className="display-6 text-warning mb-2">
                <i className="fas fa-clock"></i>
              </div>
              <h4 className="mb-1">
                {filteredBookings.filter(b => (b.room_status || b.status) === 'pending').length}
              </h4>
              <p className="text-muted mb-0">Pending</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center border-0 shadow-sm">
            <Card.Body>
              <div className="display-6 text-success mb-2">
                <i className="fas fa-check-circle"></i>
              </div>
              <h4 className="mb-1">
                {filteredBookings.filter(b => (b.room_status || b.status) === 'approved').length}
              </h4>
              <p className="text-muted mb-0">Approved</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center border-0 shadow-sm">
            <Card.Body>
              <div className="display-6 text-danger mb-2">
                <i className="fas fa-times-circle"></i>
              </div>
              <h4 className="mb-1">
                {filteredBookings.filter(b => (b.room_status || b.status) === 'rejected').length}
              </h4>
              <p className="text-muted mb-0">Rejected</p>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Filters */}
      <Row className="mb-4">
        <Col>
          <Card>
            <Card.Header>
              <h5 className="mb-0">
                <i className="fas fa-filter me-2"></i>
                Filter & Search
              </h5>
            </Card.Header>
            <Card.Body>
              <Row>
                <Col md={3}>
                  <Form.Group className="mb-3">
                    <Form.Label>Status</Form.Label>
                    <Form.Select
                      value={filters.status}
                      onChange={(e) => handleFilterChange('status', e.target.value)}
                    >
                      <option value="all">Semua Status</option>
                      <option value="pending">Pending</option>
                      <option value="approved">Approved</option>
                      <option value="rejected">Rejected</option>
                    </Form.Select>
                  </Form.Group>
                </Col>
                <Col md={3}>
                  <Form.Group className="mb-3">
                    <Form.Label>Jenis Request</Form.Label>
                    <Form.Select
                      value={filters.requestType}
                      onChange={(e) => handleFilterChange('requestType', e.target.value)}
                    >
                      <option value="all">Semua Jenis</option>
                      <option value="room">Ruangan Only</option>
                      <option value="both">Ruangan + Zoom</option>
                    </Form.Select>
                  </Form.Group>
                </Col>
                <Col md={3}>
                  <Form.Group className="mb-3">
                    <Form.Label>Dari Tanggal</Form.Label>
                    <Form.Control
                      type="date"
                      value={filters.dateFrom}
                      onChange={(e) => handleFilterChange('dateFrom', e.target.value)}
                    />
                  </Form.Group>
                </Col>
                <Col md={3}>
                  <Form.Group className="mb-3">
                    <Form.Label>Sampai Tanggal</Form.Label>
                    <Form.Control
                      type="date"
                      value={filters.dateTo}
                      onChange={(e) => handleFilterChange('dateTo', e.target.value)}
                    />
                  </Form.Group>
                </Col>
              </Row>
              <Row>
                <Col md={6}>
                  <Form.Group className="mb-3">
                    <Form.Label>Search</Form.Label>
                    <InputGroup>
                      <InputGroup.Text>
                        <i className="fas fa-search"></i>
                      </InputGroup.Text>
                      <Form.Control
                        type="text"
                        placeholder="Cari berdasarkan judul, user, atau purpose..."
                        value={filters.search}
                        onChange={(e) => handleFilterChange('search', e.target.value)}
                      />
                    </InputGroup>
                  </Form.Group>
                </Col>
                <Col md={6} className="d-flex align-items-end">
                  <Button
                    variant="outline-secondary"
                    onClick={() => setFilters({
                      status: 'all',
                      requestType: 'all',
                      search: '',
                      dateFrom: '',
                      dateTo: ''
                    })}
                    className="mb-3"
                  >
                    <i className="fas fa-undo me-2"></i>
                    Reset Filter
                  </Button>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Bookings Table */}
      <Row>
        <Col>
          <Card>
            <Card.Header className="bg-success text-white">
              <h5 className="mb-0">
                <i className="fas fa-table me-2"></i>
                History Booking ({filteredBookings.length} dari {bookings.length})
              </h5>
            </Card.Header>
            <Card.Body className="p-0">
              {filteredBookings.length > 0 ? (
                <Table responsive className="mb-0">
                  <thead className="table-light">
                    <tr>
                      <th>ID</th>
                      <th>User</th>
                      <th>Judul & Purpose</th>
                      <th>Tanggal Meeting</th>
                      <th>Waktu</th>
                      <th>Jenis</th>
                      <th>Kapasitas</th>
                      <th>Ruangan</th>
                      <th>Status</th>
                      <th>Diproses</th>
                      <th>Notes</th>
                      <th>Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredBookings.map((booking) => (
                      <tr key={booking.id}>
                        <td>
                          <Badge bg="secondary">#{booking.id}</Badge>
                        </td>
                        <td>
                          <div>
                            <strong>{booking.user_name}</strong>
                            <br />
                            <small className="text-muted">{booking.user_email}</small>
                          </div>
                        </td>
                        <td>
                          <div>
                            <strong>{booking.title}</strong>
                            <br />
                            <small className="text-muted">{booking.purpose}</small>
                          </div>
                        </td>
                        <td>{formatDate(booking.date)}</td>
                        <td>
                          <Badge bg="info">
                            {booking.start_time} - {booking.end_time}
                          </Badge>
                        </td>
                        <td>
                          {getRequestTypeBadge(booking.request_type)}
                        </td>
                        <td>
                          <Badge bg="secondary">{booking.capacity} orang</Badge>
                        </td>
                        <td>
                          {booking.room_name ? (
                            <Badge bg="info">{booking.room_name}</Badge>
                          ) : (
                            <Badge bg="secondary">Belum dialokasi</Badge>
                          )}
                        </td>
                        <td>{getStatusBadge(booking)}</td>
                        <td>
                          {booking.room_approved_at ? (
                            <small className="text-muted">
                              {formatDateTime(booking.room_approved_at)}
                            </small>
                          ) : (
                            <small className="text-muted">-</small>
                          )}
                        </td>
                        <td>
                          {booking.room_notes ? (
                            <small className="text-muted" title={booking.room_notes}>
                              {booking.room_notes.length > 30 
                                ? booking.room_notes.substring(0, 30) + '...'
                                : booking.room_notes
                              }
                            </small>
                          ) : (
                            <small className="text-muted">-</small>
                          )}
                        </td>
                        <td>
                          <Button
                            variant="info"
                            size="sm"
                            onClick={() => handleDetail(booking)}
                            title="Lihat Detail"
                          >
                            <i className="fas fa-eye"></i> Detail
                          </Button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              ) : (
                <div className="text-center py-5">
                  <i className="fas fa-history fa-3x text-muted mb-3"></i>
                  <h5>Tidak ada data booking ruangan</h5>
                  <p className="text-muted">
                    {bookings.length === 0 
                      ? 'Belum ada history booking ruangan dan zoom+ruangan'
                      : 'Tidak ada data yang sesuai dengan filter yang dipilih'
                    }
                  </p>
                  {bookings.length > 0 && (
                    <Button
                      variant="outline-primary"
                      onClick={() => setFilters({
                        status: 'all',
                        requestType: 'all',
                        search: '',
                        dateFrom: '',
                        dateTo: ''
                      })}
                    >
                      Reset Filter
                    </Button>
                  )}
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Simple Detail Modal - untuk kompatibilitas */}
      <Modal show={showDetailModal} onHide={() => setShowDetailModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>Detail Booking</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedBooking && (
            <Row>
              <Col md={6}>
                <h6>Informasi Request</h6>
                <ul className="list-unstyled">
                  <li><strong>ID:</strong> {selectedBooking.id}</li>
                  <li><strong>Judul:</strong> {selectedBooking.title}</li>
                  <li><strong>Purpose:</strong> {selectedBooking.purpose}</li>
                  <li><strong>Jenis:</strong> {getRequestTypeBadge(selectedBooking.request_type)}</li>
                  <li><strong>Status:</strong> {getStatusBadge(selectedBooking)}</li>
                </ul>
              </Col>
              <Col md={6}>
                <h6>Informasi Waktu & User</h6>
                <ul className="list-unstyled">
                  <li><strong>User:</strong> {selectedBooking.user_name}</li>
                  <li><strong>Email:</strong> {selectedBooking.user_email}</li>
                  <li><strong>Tanggal:</strong> {formatDate(selectedBooking.date)}</li>
                  <li><strong>Waktu:</strong> {selectedBooking.start_time} - {selectedBooking.end_time}</li>
                  <li><strong>Kapasitas:</strong> {selectedBooking.capacity} orang</li>
                </ul>
              </Col>
              <Col md={12}>
                <h6>Informasi Ruangan</h6>
                <ul className="list-unstyled">
                  <li><strong>Ruangan:</strong> {selectedBooking.room_name || 'Belum dialokasi'}</li>
                  <li><strong>Notes:</strong> {selectedBooking.room_notes || 'Tidak ada catatan'}</li>
                </ul>

                {/* Admin Notes Section */}
                {selectedBooking.admin_notes && (
                  <>
                    <hr />
                    <div className="alert alert-info">
                      <strong>📝 Catatan dari Admin:</strong><br />
                      {selectedBooking.admin_notes}
                    </div>
                  </>
                )}

                {selectedBooking.zoom_notes && (
                  <>
                    <hr />
                    <div className="alert alert-primary">
                      <strong>🔗 Catatan Zoom:</strong><br />
                      {selectedBooking.zoom_notes}
                    </div>
                  </>
                )}

                {selectedBooking.room_notes && selectedBooking.room_notes !== 'Tidak ada catatan' && (
                  <>
                    <hr />
                    <div className="alert alert-success">
                      <strong>🏢 Catatan Ruangan:</strong><br />
                      {selectedBooking.room_notes}
                    </div>
                  </>
                )}
              </Col>
            </Row>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowDetailModal(false)}>
            Tutup
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
};

export default RoomBookings;
